 TextView t(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.CENTER_VERTICAL);return v;} TextView b(String s,float z,int c){TextView v=t(s,z,c);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
